export interface WorldDot {
  lon: number;
  lat: number;
}

let cache: WorldDot[] | null = null;

export function getWorldDots(): WorldDot[] {
  if (cache) return cache;
  cache = ENCODED.split(",").map((hex) => {
    const code = parseInt(hex, 16);
    const latIndex = Math.floor(code / 121);
    const lonIndex = code - latIndex * 121;
    return { lon: lonIndex * 3 - 180, lat: latIndex * 3 - 84 };
  });
  return cache;
}

